"""Tests for brand.py: counts come from the repo, and stale data is refused."""

import glob
import os
import sys

import pytest
from PIL import Image

sys.path.insert(0, os.path.dirname(__file__))
import brand  # noqa: E402


def test_skill_count_matches_skill_dirs():
    expected = len(glob.glob(os.path.join(brand.ROOT, "src", "skills", "*", "SKILL.md")))
    assert expected > 0
    assert brand.skill_count() == expected


def test_skill_count_refuses_zero(monkeypatch, tmp_path):
    monkeypatch.setattr(brand, "ROOT", str(tmp_path))
    with pytest.raises(SystemExit):
        brand.skill_count()


def test_totals_agree_with_direct_counts():
    t = brand.totals()
    assert t["skills"] == brand.skill_count()
    assert t["agents"] == brand.agent_count()
    assert t["hooks"] > 0


def test_totals_refuse_stale_generated_file(monkeypatch):
    monkeypatch.setattr(brand, "skill_count", lambda: 99999)
    with pytest.raises(SystemExit):
        brand.totals()


def test_cover_returns_requested_size():
    assert brand.cover(Image.new("RGB", (2048, 1152))).size == (brand.W, brand.H)
    assert brand.cover(Image.new("RGB", (800, 800)), 2400, 1260).size == (2400, 1260)


def test_plate_index_orders_numerically():
    assert brand.plate_index("art/A-3.png") == 3
    assert brand.plate_index("art/A.png") == 0


def test_every_host_has_a_mark_source():
    marks = open(os.path.join(brand.ROOT, "docs", "site", "components", "host-marks.tsx")).read()
    for host, _ in brand.HOSTS:
        vendored = os.path.exists(os.path.join(brand.HERE, "marks", f"{host}.svg"))
        assert vendored or f"\t{host}: '" in marks, host


def test_tagline_counts_hosts_after_claude_code(monkeypatch):
    assert brand.tagline() == f"For Claude Code and {len(brand.HOSTS) - 1} more agents"
    monkeypatch.setattr(brand, "HOSTS", brand.HOSTS + [("zed", "Zed")])
    assert brand.tagline() == f"For Claude Code and {len(brand.HOSTS) - 1} more agents"


def test_tagline_refuses_a_list_that_does_not_lead_with_claude(monkeypatch):
    monkeypatch.setattr(brand, "HOSTS", list(reversed(brand.HOSTS)))
    with pytest.raises(SystemExit):
        brand.tagline()


def test_stat_words_match_the_home_page_stats_row():
    home = open(os.path.join(brand.ROOT, "docs", "site", "app", "(home)", "page.tsx")).read()
    for key, word in brand.STAT_WORDS.items():
        assert f"{{COUNTS.{key}}} {word}" in home, word


def test_warning_amber_is_not_a_card_token():
    assert not hasattr(brand, "AMBER")
